import json, sys

def brute(request):
    mem0 = tuple(request["memory"])
    progs = [list(map(list, p)) for p in request["threads"]]
    n = len(progs)
    outcomes = set()
    # full path enumeration, no dedup
    # state: mem tuple, pcs list, bufs (list of lists), obs (list of tuples)
    def rec(mem, pcs, bufs, obs):
        term = all(pcs[i] == len(progs[i]) and not bufs[i] for i in range(n))
        if term:
            outcomes.add((tuple(obs), mem))
            return
        for i in range(n):
            # drain
            if bufs[i]:
                sa, sw, sv = bufs[i][0]
                m = list(mem)
                for k in range(sw):
                    m[sa+k] = (sv >> (8*k)) & 0xff
                nb = [list(b) for b in bufs]
                nb[i] = nb[i][1:]
                rec(tuple(m), pcs, nb, obs)
            if pcs[i] < len(progs[i]):
                ins = progs[i][pcs[i]]
                op = ins[0]
